/*
 * A097151  Digits of balanced base-10 representations of nonnegative integers
 *          (least significant digits first).
 * https://oeis.org/A097151
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, sign
 * Formula:   a(n) is the nth digit (least significant first) of the *
 *            balanced base‑10 representation of successive non‑negative
 *            integers. * The digits range from –5 to +4. The sequence is
 *            generated by concatenating * those digit lists for 0, 1, 2, … .
 *            * * Algorithm: * 1. Maintain a static table `cum[k]` = to...
 * Range:     i8 n <= 112, i16 n <= 112, i32 n <= 112, i64 n <= 112,
 *            i128 n <= 112, big any n
 * Helpers:   balanced_digit_at, balanced_length
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include "../utils/balanced_digit_at.h"
#include "../utils/balanced_length.h"

/* Main sequence function.  Static state keeps the cumulative digit counts
 * between calls so that each `n` is answered in amortised O(1) time. */
seq_t a(idx_t n) {
    static idx_t *cum = NULL;   /* cumulative digit counts, cum[k] = total up to k */
    static size_t cap = 0;      /* allocated capacity */
    static size_t sz = 0;       /* number of entries present (>=1 after init) */

    if (sz == 0) {              /* initialise for the first call */
        cap = 16;
        cum = (idx_t *)malloc(cap * sizeof(idx_t));
        if (!cum) return (seq_t)0;     /* allocation failed, return 0 as fallback */
        cum[0] = 1;                /* digits up to number 0 */
        sz = 1;
    }

    /* Extend the cumulative array until it covers the desired index `n`. */
    while (n > cum[sz - 1]) {
        idx_t k = sz;     /* we are about to add digits for integer `k` */
        idx_t len_k = balanced_length(k);
        idx_t new_cum = cum[sz - 1] + len_k;

        if (sz == cap) {          /* grow the array */
            cap = cap * 2;
            idx_t *tmp = (idx_t *)realloc(cum, cap * sizeof(idx_t));
            if (!tmp) {           /* allocation failed: keep old data, return 0 */
                if (cum) free(cum);
                return (seq_t)0;
            }
            cum = tmp;
        }
        cum[sz] = new_cum;
        sz++;
    }

    /* Find the integer `k` where `n` falls into its digit block. */
    idx_t k = sz - 1;                  /* integer whose block contains n */
    idx_t cum_prev = (sz > 1) ? cum[sz - 2] : 0;
    idx_t pos = n - cum_prev;          /* 1‑based position within k's digits */

    return balanced_digit_at(k, pos);
}
